//! Coordinator preparation captures generated bytes; consumers never read live OUT_DIR.
use super::snapshot::SourcePath;
use crate::{
    core::{
        diagnostic::Diagnostic,
        digest::{Digest, StableEncode, StableEncoder},
    },
    project::cargo_units::{CargoUnitKey, TargetKind, UnitRole},
};
use cap_std::fs::{Dir, Metadata};
use serde::{Deserialize, Serialize};
use std::{
    collections::{BTreeMap, BTreeSet, VecDeque},
    io::Read,
    path::{Path, PathBuf},
};
const MAX_FILES: usize = 100_000;
const MAX_FILE_BYTES: usize = 8 * 1024 * 1024;
const MAX_TREE_BYTES: usize = 128 * 1024 * 1024;
const MAX_DEPTH: usize = 256;
fn fault(message: impl Into<String>) -> Diagnostic {
    Diagnostic::new("LRR-E-GENERATED-SOURCE", message.into())
}
fn race() -> Diagnostic {
    Diagnostic::new(
        "LRR-E-SNAPSHOT-RACE",
        "generated output changed during capture; repeat explicit preparation".into(),
    )
}
#[derive(Debug, Clone, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GeneratedBlob {
    producer: Digest,
    path: SourcePath,
    original_path: String,
    content: Digest,
    bytes: Vec<u8>,
}
impl GeneratedBlob {
    pub fn producer(&self) -> Digest {
        self.producer
    }
    pub fn path(&self) -> &SourcePath {
        &self.path
    }
    pub fn original_path(&self) -> &str {
        &self.original_path
    }
    pub fn content(&self) -> Digest {
        self.content
    }
    pub fn bytes(&self) -> &[u8] {
        &self.bytes
    }
}
impl StableEncode for GeneratedBlob {
    const DOMAIN: &'static str = "lrr/v2/generated-blob";
    fn encode_fields(&self, e: &mut StableEncoder) {
        e.digest(self.producer);
        e.string(self.path.as_str());
        e.string(&self.original_path);
        e.digest(self.content);
    }
}
#[derive(Debug, Clone, Eq, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct GeneratedTree {
    producer: Digest,
    out_dir: String,
    directories: BTreeSet<SourcePath>,
    files: BTreeMap<SourcePath, GeneratedBlob>,
}
impl GeneratedTree {
    pub fn producer(&self) -> Digest {
        self.producer
    }
    pub fn out_dir(&self) -> &str {
        &self.out_dir
    }
    pub fn directories(&self) -> &BTreeSet<SourcePath> {
        &self.directories
    }
    pub fn files(&self) -> &BTreeMap<SourcePath, GeneratedBlob> {
        &self.files
    }
    pub fn membership_fingerprint(&self) -> Digest {
        let mut e = StableEncoder::new("lrr/v2/generated-membership");
        e.digest(self.producer);
        e.string(&self.out_dir);
        e.sequence(&self.directories.iter().collect::<Vec<_>>(), |e, path| {
            e.string(path.as_str())
        });
        e.sequence(&self.files.keys().collect::<Vec<_>>(), |e, path| {
            e.string(path.as_str())
        });
        e.finish()
    }
    pub fn validate(&self) -> Result<(), Diagnostic> {
        let root = Path::new(&self.out_dir);
        if !root.is_absolute()
            || self.out_dir.contains('\0')
            || self
                .files
                .len()
                .checked_add(self.directories.len())
                .is_none_or(|n| n > MAX_FILES)
        {
            return Err(fault("invalid generated output root/membership"));
        }
        let mut total = 0usize;
        for (path, blob) in &self.files {
            if path != &blob.path
                || blob.producer != self.producer
                || blob.bytes.len() > MAX_FILE_BYTES
                || blob.content != Digest::of_bytes(&blob.bytes)
                || Path::new(&blob.original_path) != root.join(path.as_str())
                || self.directories.contains(path)
            {
                return Err(fault("generated blob key/origin/content mismatch"));
            }
            total = total
                .checked_add(blob.bytes.len())
                .ok_or_else(|| fault("generated size overflow"))?;
        }
        if total > MAX_TREE_BYTES {
            return Err(fault("generated tree exceeds 128 MiB"));
        }
        for path in self.files.keys().chain(&self.directories) {
            if Path::new(path.as_str()).components().count() > MAX_DEPTH {
                return Err(fault("generated path depth exceeded"));
            }
            let mut parent = Path::new(path.as_str()).parent();
            while let Some(p) = parent.filter(|p| !p.as_os_str().is_empty()) {
                if !self.directories.contains(&SourcePath::new(p)?) {
                    return Err(fault("generated parent directory missing from membership"));
                }
                parent = p.parent();
            }
        }
        Ok(())
    }
}
impl StableEncode for GeneratedTree {
    const DOMAIN: &'static str = "lrr/v2/generated-tree";
    fn encode_fields(&self, e: &mut StableEncoder) {
        e.digest(self.producer);
        e.string(&self.out_dir);
        e.u64(self.directories.len() as u64);
        for path in &self.directories {
            e.string(path.as_str());
        }
        e.map(&self.files, |e, path, blob| {
            e.string(path.as_str());
            e.record(blob);
        });
    }
}
#[derive(Debug, Clone, Eq, PartialEq)]
struct Stamp {
    len: u64,
    modified: Option<cap_std::time::SystemTime>,
    dev: u64,
    ino: u64,
    ctime: i64,
    ctime_nsec: i64,
}
impl Stamp {
    fn of(m: &Metadata) -> Self {
        use cap_std::fs::MetadataExt;
        Self {
            len: m.len(),
            modified: m.modified().ok(),
            dev: m.dev(),
            ino: m.ino(),
            ctime: m.ctime(),
            ctime_nsec: m.ctime_nsec(),
        }
    }
}
#[derive(Eq, PartialEq)]
struct Captured {
    tree: GeneratedTree,
    stamps: BTreeMap<PathBuf, (PathBuf, Stamp, Stamp)>,
}
/// Opening is an explicit preparation-side grant for one Cargo-reported OUT_DIR.
/// No build process, macro execution, or native-runtime permission is conferred.
pub struct GeneratedRoot {
    directory: Dir,
    producer: Digest,
    original: String,
}
impl GeneratedRoot {
    pub fn open(unit: &CargoUnitKey, out_dir: &Path) -> Result<Self, Diagnostic> {
        if unit.role != UnitRole::BuildHost || unit.target_kind != TargetKind::BuildScript {
            return Err(fault(
                "OUT_DIR producer must be the exact build-script unit",
            ));
        }
        if !out_dir.is_absolute() {
            return Err(fault("Cargo OUT_DIR must be absolute"));
        }
        let original = out_dir
            .to_str()
            .ok_or_else(|| fault("OUT_DIR must be UTF-8"))?
            .to_owned();
        let directory = Dir::open_ambient_dir(out_dir, cap_std::ambient_authority())
            .map_err(|e| fault(e.to_string()))?;
        Ok(Self {
            directory,
            producer: unit.fingerprint(),
            original,
        })
    }
    pub fn capture(&self) -> Result<GeneratedTree, Diagnostic> {
        self.capture_with(|| {})
    }
    pub(crate) fn capture_with(
        &self,
        between_reads: impl FnOnce(),
    ) -> Result<GeneratedTree, Diagnostic> {
        let first = self.scan()?;
        between_reads();
        let second = self.scan()?;
        if first != second {
            return Err(race());
        }
        first.tree.validate()?;
        Ok(first.tree)
    }
    fn scan(&self) -> Result<Captured, Diagnostic> {
        self.verify_root()?;
        let mut tree = GeneratedTree {
            producer: self.producer,
            out_dir: self.original.clone(),
            directories: BTreeSet::new(),
            files: BTreeMap::new(),
        };
        let mut stamps = BTreeMap::new();
        let mut pending = VecDeque::from([(PathBuf::from("."), Vec::<PathBuf>::new())]);
        let mut total = 0usize;
        while let Some((path, ancestors)) = pending.pop_front() {
            if stamps.len() >= MAX_FILES || ancestors.len() >= MAX_DEPTH {
                return Err(fault("generated membership/depth limit"));
            }
            let canonical = self
                .directory
                .canonicalize(&path)
                .map_err(|e| fault(format!("generated path {}: {e}", path.display())))?;
            let link = self.directory.symlink_metadata(&path).map_err(|_| race())?;
            let metadata = self.directory.metadata(&path).map_err(|_| race())?;
            stamps.insert(
                path.clone(),
                (canonical.clone(), Stamp::of(&link), Stamp::of(&metadata)),
            );
            if metadata.is_dir() {
                if ancestors.contains(&canonical) {
                    return Err(fault("generated directory symlink cycle"));
                }
                if path != Path::new(".") {
                    tree.directories.insert(SourcePath::new(&path)?);
                }
                let mut parents = ancestors;
                parents.push(canonical);
                let mut names = BTreeSet::new();
                for entry in self.directory.read_dir(&path).map_err(|_| race())? {
                    let name = entry.map_err(|_| race())?.file_name();
                    if name.to_str().is_none() {
                        return Err(fault("generated filename must be UTF-8"));
                    }
                    names.insert(name);
                    if names
                        .len()
                        .checked_add(pending.len())
                        .and_then(|n| n.checked_add(stamps.len()))
                        .is_none_or(|n| n > MAX_FILES)
                    {
                        return Err(fault("generated membership limit"));
                    }
                }
                for name in names {
                    pending.push_back((path.join(name), parents.clone()));
                }
            } else if metadata.is_file() {
                if metadata.len() > MAX_FILE_BYTES as u64 {
                    return Err(fault("generated file exceeds 8 MiB"));
                }
                let mut file = self.directory.open(&path).map_err(|_| race())?;
                if Stamp::of(&file.metadata().map_err(|_| race())?) != Stamp::of(&metadata) {
                    return Err(race());
                }
                let mut bytes = vec![];
                let mut buffer = [0; 16 * 1024];
                loop {
                    let count = file.read(&mut buffer).map_err(|_| race())?;
                    if count == 0 {
                        break;
                    }
                    if bytes
                        .len()
                        .checked_add(count)
                        .is_none_or(|n| n > MAX_FILE_BYTES)
                    {
                        return Err(fault("generated file exceeds 8 MiB"));
                    }
                    bytes.extend_from_slice(&buffer[..count]);
                }
                if Stamp::of(&file.metadata().map_err(|_| race())?) != Stamp::of(&metadata) {
                    return Err(race());
                }
                total = total
                    .checked_add(bytes.len())
                    .ok_or_else(|| fault("generated size overflow"))?;
                if total > MAX_TREE_BYTES {
                    return Err(fault("generated tree exceeds 128 MiB"));
                }
                let relative = SourcePath::new(&path)?;
                tree.files.insert(
                    relative.clone(),
                    GeneratedBlob {
                        producer: self.producer,
                        path: relative.clone(),
                        original_path: Path::new(&self.original)
                            .join(relative.as_str())
                            .to_str()
                            .ok_or_else(|| fault("generated original path must be UTF-8"))?
                            .to_owned(),
                        content: Digest::of_bytes(&bytes),
                        bytes,
                    },
                );
            } else {
                return Err(fault(
                    "generated outputs must be regular files or directories",
                ));
            }
        }
        for (path, (canonical, link, target)) in &stamps {
            if self.directory.canonicalize(path).map_err(|_| race())? != *canonical
                || Stamp::of(&self.directory.symlink_metadata(path).map_err(|_| race())?) != *link
                || Stamp::of(&self.directory.metadata(path).map_err(|_| race())?) != *target
            {
                return Err(race());
            }
        }
        self.verify_root()?;
        Ok(Captured { tree, stamps })
    }
    fn verify_root(&self) -> Result<(), Diagnostic> {
        let current = Dir::open_ambient_dir(&self.original, cap_std::ambient_authority())
            .map_err(|_| race())?;
        if Stamp::of(&current.dir_metadata().map_err(|_| race())?)
            != Stamp::of(&self.directory.dir_metadata().map_err(|_| race())?)
        {
            return Err(race());
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::{
        fs,
        sync::{Arc, Barrier},
        time::{SystemTime, UNIX_EPOCH},
    };
    struct Fixture(PathBuf);
    impl Fixture {
        fn new() -> Self {
            static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);
            let counter = NEXT
                .try_update(
                    std::sync::atomic::Ordering::Relaxed,
                    std::sync::atomic::Ordering::Relaxed,
                    |n| n.checked_add(1),
                )
                .unwrap();
            let path = std::env::temp_dir().join(format!(
                "lrr-generated-{}-{}-{counter}",
                std::process::id(),
                SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .unwrap()
                    .as_nanos()
            ));
            fs::create_dir(&path).unwrap();
            Self(path)
        }
    }
    impl Drop for Fixture {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }
    fn unit(feature: &str) -> CargoUnitKey {
        CargoUnitKey {
            package: "path+file:///fixture#same_package@0.1.0".into(),
            target_name: "build-script-build".into(),
            target_kind: TargetKind::BuildScript,
            role: UnitRole::BuildHost,
            compile_target: crate::core::profile::GUEST_TARGET.into(),
            test_intent: false,
            edition: 2024,
            features: BTreeSet::from([feature.into()]),
            profile_fingerprint: Digest::of_bytes(b"fixture-profile"),
            cfg_fingerprint: Digest::of_bytes(b"fixture-cfg"),
            dependency_edges: Digest::of_bytes(b"fixture-edges"),
            rustc_fingerprint: Digest::of_bytes(b"fixture-compiler"),
        }
    }
    #[test]
    fn generated_outputs_with_same_filename_remain_scoped_to_exact_unit() {
        let a = Fixture::new();
        let b = Fixture::new();
        fs::write(a.0.join("generated.rs"), "11_i64\n").unwrap();
        fs::write(b.0.join("generated.rs"), "29_i64\n").unwrap();
        let one = GeneratedRoot::open(&unit("a"), &a.0)
            .unwrap()
            .capture()
            .unwrap();
        let two = GeneratedRoot::open(&unit("b"), &b.0)
            .unwrap()
            .capture()
            .unwrap();
        let path = SourcePath::new("generated.rs").unwrap();
        assert_ne!(one.producer(), two.producer());
        assert_eq!(
            one.files()[&path].bytes(),
            fs::read(a.0.join("generated.rs")).unwrap()
        );
        assert_eq!(
            two.files()[&path].bytes(),
            fs::read(b.0.join("generated.rs")).unwrap()
        );
        assert_ne!(one.files()[&path].content(), two.files()[&path].content());
        fs::write(a.0.join("generated.rs"), "changed after capture").unwrap();
        assert_eq!(one.files()[&path].bytes(), b"11_i64\n");
        assert_eq!(
            GeneratedRoot::open(&unit("b"), &b.0)
                .unwrap()
                .capture()
                .unwrap()
                .fingerprint(),
            two.fingerprint()
        );
    }
    #[test]
    fn concurrent_generated_write_rejects_capture_then_stable_capture_succeeds() {
        let fixture = Fixture::new();
        let path = fixture.0.join("generated.rs");
        fs::write(&path, "before").unwrap();
        let root = GeneratedRoot::open(&unit("race"), &fixture.0).unwrap();
        let barrier = Arc::new(Barrier::new(2));
        let writer_barrier = barrier.clone();
        let writer = std::thread::spawn(move || {
            writer_barrier.wait();
            fs::write(path, "after").unwrap();
            writer_barrier.wait();
        });
        let error = root
            .capture_with(|| {
                barrier.wait();
                barrier.wait();
            })
            .unwrap_err();
        writer.join().unwrap();
        assert_eq!(error.code, "LRR-E-SNAPSHOT-RACE");
        let stable = root.capture().unwrap();
        assert_eq!(
            stable.files()[&SourcePath::new("generated.rs").unwrap()].bytes(),
            fs::read(fixture.0.join("generated.rs")).unwrap()
        );
    }
    #[test]
    fn generated_membership_and_symlink_authority_are_verified() {
        use std::os::unix::fs::symlink;
        let root = Fixture::new();
        let outside = Fixture::new();
        fs::create_dir(root.0.join("nested")).unwrap();
        fs::write(root.0.join("nested/bytes.bin"), [0xff, 0, 1]).unwrap();
        symlink("nested/bytes.bin", root.0.join("alias.bin")).unwrap();
        let capture = GeneratedRoot::open(&unit("paths"), &root.0).unwrap();
        let before = capture.capture().unwrap();
        assert_eq!(
            before.files()[&SourcePath::new("alias.bin").unwrap()].bytes(),
            [0xff, 0, 1]
        );
        let error = capture
            .capture_with(|| {
                fs::write(root.0.join("added.rs"), "new member").unwrap();
            })
            .unwrap_err();
        assert_eq!(error.code, "LRR-E-SNAPSHOT-RACE");
        assert_ne!(
            before.fingerprint(),
            capture.capture().unwrap().fingerprint()
        );
        fs::write(outside.0.join("secret"), "outside").unwrap();
        symlink(outside.0.join("secret"), root.0.join("escape")).unwrap();
        assert_eq!(
            capture.capture().unwrap_err().code,
            "LRR-E-GENERATED-SOURCE"
        );
        fs::remove_file(root.0.join("escape")).unwrap();
        symlink(".", root.0.join("cycle")).unwrap();
        assert_eq!(
            capture.capture().unwrap_err().code,
            "LRR-E-GENERATED-SOURCE"
        );
    }
    #[test]
    fn generated_serialized_content_is_validated_not_trusted_by_hash() {
        let root = Fixture::new();
        fs::write(root.0.join("generated.rs"), "content").unwrap();
        let tree = GeneratedRoot::open(&unit("decode"), &root.0)
            .unwrap()
            .capture()
            .unwrap();
        let value = serde_json::to_value(&tree).unwrap();
        let decoded: GeneratedTree = serde_json::from_value(value.clone()).unwrap();
        decoded.validate().unwrap();
        assert_eq!(tree.fingerprint(), decoded.fingerprint());
        let mut wrong = value.clone();
        wrong["files"]["generated.rs"]["bytes"] = serde_json::json!([1, 2]);
        assert_eq!(
            serde_json::from_value::<GeneratedTree>(wrong)
                .unwrap()
                .validate()
                .unwrap_err()
                .code,
            "LRR-E-GENERATED-SOURCE"
        );
        let mut unknown = value;
        unknown["unexpected"] = serde_json::json!(true);
        assert!(serde_json::from_value::<GeneratedTree>(unknown).is_err());
    }
    #[test]
    fn replaced_out_dir_and_runtime_unit_producers_are_rejected() {
        let fixture = Fixture::new();
        let mut runtime = unit("role");
        runtime.role = UnitRole::Live;
        assert!(
            matches!(GeneratedRoot::open(&runtime, Path::new("/missing/out-dir")), Err(e) if e.code == "LRR-E-GENERATED-SOURCE")
        );
        fs::write(fixture.0.join("generated.rs"), "old directory").unwrap();
        let root = GeneratedRoot::open(&unit("role"), &fixture.0).unwrap();
        let retained = fixture.0.with_extension("retained");
        fs::rename(&fixture.0, &retained).unwrap();
        fs::create_dir(&fixture.0).unwrap();
        fs::write(fixture.0.join("generated.rs"), "replacement").unwrap();
        let error = root.capture().unwrap_err();
        fs::remove_dir_all(&retained).unwrap();
        assert_eq!(error.code, "LRR-E-SNAPSHOT-RACE");
    }
}
